SELECT DATE_TRUNC('MONTH', opened_date) opened_month, SORT_ARRAY(COLLECT_SET(region)) region_list, MAX(sqft) - MIN(sqft) sqft_range, ROUND((100 * SUM(CASE WHEN region = 'East' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_east FROM stores WHERE store_name LIKE 'A%' GROUP BY DATE_TRUNC('MONTH', opened_date) HAVING ROUND((100 * SUM(CASE WHEN region = 'East' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 36;
